package store.model;

import java.util.*;

public final class Domain {
    private Domain() { }
    public enum LoyaltyTier { REGULAR, SILVER, GOLD }
    public enum OrderStatus { CREATED, PAID, CANCELLED, REFUNDED }
    public enum CashflowType { INFLOW, OUTFLOW }
    public enum ShippingMethod { STANDARD, EXPRESS, PICKUP }
    public static final class Category { private final String id,name; public Category(String i,String n){id=i;name=n;} public String getId(){return id;} public String getName(){return name;} }
    public static final class Product { private final String id,name; private final double price; private final Category category; private int stock; private boolean active=true; public Product(String i,String n,double p,Category c){if(p<0)throw new IllegalArgumentException("Negative price");id=i;name=n;price=p;category=c;} public String getId(){return id;} public String getName(){return name;} public double getUnitPrice(){return price;} public Category getCategory(){return category;} public int getStock(){return stock;} public boolean isActive(){return active;} public void setActive(boolean a){active=a;} public void increaseStock(int q){if(q<=0)throw new IllegalArgumentException("Quantity must be positive");stock+=q;} public void decreaseStock(int q){if(q<=0||q>stock)throw new IllegalArgumentException("Insufficient stock or invalid quantity");stock-=q;} }
    public static final class Customer { private final String id,name; private final LoyaltyTier tier; public Customer(String i,String n,LoyaltyTier t){id=i;name=n;tier=t;} public String getId(){return id;} public String getName(){return name;} public LoyaltyTier getTier(){return tier;} }
    public static final class Supplier { private final String id,name; public Supplier(String i,String n){id=i;name=n;} public String getId(){return id;} public String getName(){return name;} }
    public static final class CartItem { private final Product product; private int quantity; public CartItem(Product p,int q){product=p;setQuantity(q);} public Product getProduct(){return product;} public int getQuantity(){return quantity;} public void setQuantity(int q){if(q<=0)throw new IllegalArgumentException("Quantity must be positive");quantity=q;} public double subtotal(){return quantity*product.getUnitPrice();} }
    public static final class Cart { private final String id; private final Customer customer; private final Map<String,CartItem> items=new LinkedHashMap<>(); public Cart(String i,Customer c){id=i;customer=c;} public String getId(){return id;} public Customer getCustomer(){return customer;} public Collection<CartItem> getItems(){return items.values();} public void add(Product p,int q){if(!p.isActive())throw new IllegalArgumentException("Inactive product");if(q<=0)throw new IllegalArgumentException("Quantity must be positive");CartItem x=items.get(p.getId());if(x==null)items.put(p.getId(),new CartItem(p,q));else x.setQuantity(x.getQuantity()+q);} public void update(String id,int q){CartItem x=items.get(id);if(x==null)throw new IllegalArgumentException("Product not in cart");x.setQuantity(q);} public void remove(String id){if(items.remove(id)==null)throw new IllegalArgumentException("Product not in cart");} public double subtotal(){return items.values().stream().mapToDouble(CartItem::subtotal).sum();} }
    public static final class OrderItem { private final Product product; private final int quantity; private final double unitPrice; public OrderItem(Product p,int q){product=p;quantity=q;unitPrice=p.getUnitPrice();} public Product getProduct(){return product;} public int getQuantity(){return quantity;} public double getUnitPrice(){return unitPrice;} public double subtotal(){return quantity*unitPrice;} }
    public static final class Order { private final String id; private final Customer customer; private final List<OrderItem> items; private OrderStatus status=OrderStatus.CREATED; private double discount,shipping; public Order(String i,Customer c,List<OrderItem> x){if(x.isEmpty())throw new IllegalArgumentException("Order must have items");id=i;customer=c;items=new ArrayList<>(x);} public String getId(){return id;} public Customer getCustomer(){return customer;} public List<OrderItem> getItems(){return Collections.unmodifiableList(items);} public OrderStatus getStatus(){return status;} public void setStatus(OrderStatus s){status=s;} public double getSubtotal(){return items.stream().mapToDouble(OrderItem::subtotal).sum();} public double getPromotionDiscount(){return discount;} public void setPromotionDiscount(double d){if(d<0)throw new IllegalArgumentException("Negative discount");discount=d;} public double getShipping(){return shipping;} public void setShipping(double s){if(s<0)throw new IllegalArgumentException("Negative shipping");shipping=s;} public double getTotal(){return getSubtotal()-discount+shipping;} }
    public interface Promotion { double discount(Order o); }
    public static final class PercentagePromotion implements Promotion { private final double rate,threshold; public PercentagePromotion(double r,double t){rate=r;threshold=t;} public double discount(Order o){return o.getSubtotal()>=threshold?o.getSubtotal()*rate:0;} }
    public static final class FixedPromotion implements Promotion { private final double amount,threshold; private final LoyaltyTier tier; public FixedPromotion(double a,double t,LoyaltyTier l){amount=a;threshold=t;tier=l;} public double discount(Order o){return o.getSubtotal()>=threshold&&o.getCustomer().getTier()==tier?amount:0;} }
    public static final class BuyXGetYPromotion implements Promotion { private final String product; private final int buy,get; public BuyXGetYPromotion(String p,int b,int g){product=p;buy=b;get=g;} public double discount(Order o){for(OrderItem i:o.getItems())if(i.getProduct().getId().equals(product))return i.getQuantity()/(buy+get)*get*i.getUnitPrice();return 0;} }
    public static final class Payment { private final String id,order; private final double amount; public Payment(String i,String o,double a){if(a<0)throw new IllegalArgumentException("Negative payment");id=i;order=o;amount=a;} public String getId(){return id;} public String getOrderId(){return order;} public double getAmount(){return amount;} }
    public static final class ReturnRequest { private final String id; private final Order order; private final Map<String,Integer> items=new LinkedHashMap<>(); private boolean processed; public ReturnRequest(String i,Order o){id=i;order=o;} public String getId(){return id;} public Order getOrder(){return order;} public Map<String,Integer> getItems(){return Collections.unmodifiableMap(items);} public boolean isProcessed(){return processed;} public void add(Product p,int q){if(q<=0)throw new IllegalArgumentException("Quantity must be positive");items.merge(p.getId(),q,Integer::sum);} public void markProcessed(){processed=true;} public double total(){return items.entrySet().stream().mapToDouble(e->order.getItems().stream().filter(i->i.getProduct().getId().equals(e.getKey())).findFirst().orElseThrow().getUnitPrice()*e.getValue()).sum();} }
    public static final class Restock { private final String id; private final Product product; private final Supplier supplier; private final int quantity; private final double total; public Restock(String i,Product p,Supplier s,int q,double c){if(q<=0||c<0)throw new IllegalArgumentException("Invalid restock");id=i;product=p;supplier=s;quantity=q;total=q*c;} public String getId(){return id;} public Product getProduct(){return product;} public Supplier getSupplier(){return supplier;} public int getQuantity(){return quantity;} public double getTotal(){return total;} }
    public static final class CashflowEntry { private final CashflowType type; private final String description; private final double amount; public CashflowEntry(CashflowType t,String d,double a){if(a<0)throw new IllegalArgumentException("Negative amount");type=t;description=d;amount=a;} public CashflowType getType(){return type;} public String getDescription(){return description;} public double getAmount(){return amount;} }
}
